import base64

kind = str(feed.get("auth_kind") or "none").strip().lower()
if kind == "none" or not feed.get("credential_id"):
    return {}

rows = db.query(
    "SELECT name FROM credential WHERE id = %s AND org_id = %s",
    [feed["credential_id"], org_id], org_id,
)
if not rows:
    raise KeyError("this feed names a credential that no longer exists")
secret = provider.resolve(org_id, rows[0]["name"]).reveal()

if kind == "basic":
    # Stored as user:password, which is what Basic wants. Encoded whole
    # rather than split, because passwords contain colons.
    encoded = base64.b64encode(secret.encode("utf-8")).decode("ascii")
    return {"Authorization": "Basic " + encoded}
if kind == "bearer":
    return {"Authorization": "Bearer " + secret}
if kind == "header":
    # The whole header value, for servers that want an unusual scheme.
    return {"Authorization": secret}
raise ValueError("unsupported TAXII auth kind %r" % kind)

kind = job.get("kind")
if kind == "feed_fetch":
    return run_feed_fetch(db, provider, job)
if kind == "taxii_poll":
    return run_taxii_poll(db, provider, job)
if kind == "taxii_discover":
    return run_taxii_discover(db, provider, job)
if kind in ("attack_sync", "mitre_sync"):
    return run_attack_sync(db, job)
if kind == "health_check":
    return run_health_probe(db, job)
if kind == "alert_poll":
    return run_alert_poll(db, provider, job)
if kind == "hunt_run":
    return run_hunt(db, provider, job)
return {"ok": False, "reason": "no handler for job kind %r" % kind}
